// CSD_RATIONALE_BEGIN
// SQL-single-query CSD with visible constrained spans. The strategy tracks the
// ordinary generated prefix plus whether we are currently inside the SQL span;
// inside the span it also tracks the constrained SQL prefix itself. Outside the
// span, it first ensures entry into a visible constrained region so the SQL is
// parser-controlled. Inside the span, it chooses between a one-token adaptive
// constrained step and a bounded multi-token constrained-symbol step based on
// parser narrowness and the available per-iteration token budget.
// Soft preferences come from caller-supplied validTokenGroups, while parser
// validity remains the hard authority. If a constrained prefix becomes long and
// narrow without completing, the strategy can roll back the constrained suffix
// to a valid prefix and continue. This tracked state supports valid SQL
// generation because every committed inside-span extension is either returned by
// a parser-constrained helper or repaired back to a parser-valid prefix before
// further decoding.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span branch, OpenConstrainedSpan or
//   EnterObservedConstrainedSpan sets currentConstrainedOut := [], which is a
//   valid prefix by the method precondition parser.IsValidPrefix([]); ordinary
//   unconstrained tokens leave insideConstrainedOut false, so the implication is
//   vacuous. In the complete-prefix branch, CloseConstrainedSpan exits the span,
//   so the implication is again vacuous.
//   In the rollback branch, RollbackConstrainedSuffix returns a repaired
//   constrained prefix that is parser-valid. In the one-token constrained
//   branch, AdaptiveConstrainedStep returns EOS or a parser-valid next token;
//   on non-EOS we commit it with AppendConstrainedToken, preserving validity. In
//   the symbol branch, ConstrainedSymbolInGenerated returns currentOut that is a
//   valid parser prefix, so assigning it preserves the invariant.
// progress: OpenConstrainedSpan, EnterObservedConstrainedSpan bookkeeping plus
//   the observed-open path, CloseConstrainedSpan, rollback bookkeeping, and each
//   one-token constrained helper are paired with explicit steps increments equal
//   to their consumed token budget: +1 for OpenConstrainedSpan,
//   CloseConstrainedSpan, UnconstrainedStep, and AdaptiveConstrainedStep; +0 for
//   EnterObservedConstrainedSpan bookkeeping itself after the already-generated
//   observed delimiter; +1 for the rollback branch as a conservative progress
//   charge while visible output does not grow.
//   In the symbol branch, steps increases by stepsUsed, and visible growth is at
//   most the accepted constrained-prefix growth, which is bounded by stepsUsed;
//   rejected suffix tokens or EOS may consume budget without visible growth, so
//   |generated| <= |generatedPrefix| + steps is preserved. Thus every branch
//   maintains the progress invariant.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 16;
var rollbackLimit: nat := 96;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if |generated| > 0 && generated[|generated| - 1] == "<<" {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
    } else {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      steps := steps + 1;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit && helpers.DeadEndDetection(parser, currentConstrainedOut, 2) {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var remaining: nat := maxSteps - steps;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if stepTokenBudget <= 1 || remaining <= 1 || validCount <= narrowThreshold {
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      currentConstrainedOut := symbolOut;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

